class NextStackingCards{constructor(element){this.element=element;this.cards=[...element.querySelectorAll(".dan-stacking-cards__card")];this.timelines=[];this.config=this.initConfig();this.init()}
static instances=[];static observer=null;static refreshHandlersBound=!1;static destroyAll(){NextStackingCards.instances.forEach((instance)=>instance.destroy());NextStackingCards.instances=[]}
static refreshScrollTrigger(){const scrollTriggerPlugin=window.ScrollTrigger||(typeof ScrollTrigger!=="undefined"?ScrollTrigger:null);if(scrollTriggerPlugin&&typeof scrollTriggerPlugin.refresh==="function"){scrollTriggerPlugin.refresh()}}
static bindRefreshHandlers(){if(NextStackingCards.refreshHandlersBound){return}
NextStackingCards.refreshHandlersBound=!0;window.addEventListener("load",()=>NextStackingCards.refreshScrollTrigger(),{once:!0});window.addEventListener("pageshow",()=>NextStackingCards.refreshScrollTrigger())}
initConfig(){return{finalBrightness:this.element.getAttribute("data-final-brightness"),scale:parseFloat(this.element.getAttribute("data-scale")),borderRadius:parseFloat(this.element.getAttribute("data-border-radius")),start:this.element.getAttribute("data-start"),end:this.element.getAttribute("data-end"),easing:this.element.getAttribute("data-easing"),}}
createCardAnimation(card,position){const isLast=position===this.cards.length-1;const timeline=gsap.timeline({scrollTrigger:{trigger:card,start:this.config.start,end:this.config.end,scrub:!0,invalidateOnRefresh:!0,},});timeline.to(card,{ease:this.config.easing,startAt:{filter:"brightness(100%)"},filter:isLast?"none":`brightness(${parseFloat(this.config.finalBrightness)}%)`,scale:this.config.scale,borderRadius:this.config.borderRadius,},0);this.timelines.push(timeline)}
init(){this.cards.forEach((card,index)=>{this.createCardAnimation(card,index)})}
destroy(){this.timelines.forEach((timeline)=>{if(timeline.scrollTrigger){timeline.scrollTrigger.kill()}
timeline.kill()});this.cards.forEach((card)=>{gsap.set(card,{clearProps:"all"})});this.timelines=[];this.cards=[];this.element=null}}
function dancepad_stacking_cards(){NextStackingCards.destroyAll();document.querySelectorAll(".dan-stacking-cards").forEach((element)=>{const instance=new NextStackingCards(element);NextStackingCards.instances.push(instance)});initializeStackingCardsObserver();requestAnimationFrame(()=>NextStackingCards.refreshScrollTrigger());NextStackingCards.bindRefreshHandlers()}
function initializeStackingCardsObserver(){if(NextStackingCards.observer){NextStackingCards.observer.disconnect();NextStackingCards.observer=null}
const breakdanceCanvas=document.querySelector("#breakdance_canvas");if(!breakdanceCanvas){return}
NextStackingCards.observer=new MutationObserver((mutations)=>{for(const mutation of mutations){if(mutation.type==="childList"){const hasChanges=[...mutation.addedNodes,...mutation.removedNodes].some((node)=>node.classList&&node.classList.contains("dan-stacking-cards__card"));if(hasChanges){dancepad_stacking_cards();break}}}});document.querySelectorAll(".dan-stacking-cards").forEach((element)=>{NextStackingCards.observer.observe(element,{childList:!0,subtree:!0})})}